import 'dart:convert';

import 'qr_payload.dart';
import 'transaction.dart';

/// The two kinds of QR message OfflinePay exchanges between devices.
///
/// QR is only the transport - it carries JSON from one phone to another.
/// The protocol has exactly two message types:
///
///   1. PAYMENT_REQUEST      receiver -> payer
///      "Bob wants ₹100, here is who to pay" (generated by Receive screen)
///
///   2. TRANSACTION_RECEIPT  payer -> receiver
///      "Alice created this transaction, here it is to record" (shown by the
///      payer after confirming; scanned by Bob to book the incoming payment)
///
/// This two-message ping-pong is what lets a full payment complete with
/// ZERO internet: request over there, receipt back here, both devices keep
/// a matching PENDING_SYNC ledger entry, and Phase 6 sync reconciles them.
sealed class QrMessage {
  const QrMessage();

  /// Decode a raw QR string into a typed message.
  ///
  /// Throws [FormatException] with a human-readable message - the UI shows
  /// it directly, so never replace these with technical jargon.
  factory QrMessage.decode(String raw) {
    dynamic data;
    try {
      data = jsonDecode(raw);
    } on FormatException {
      throw const FormatException('This is not a valid OfflinePay QR code.');
    }

    if (data is! Map<String, dynamic>) {
      throw const FormatException('QR code does not contain a JSON object.');
    }

    switch (data['type']) {
      case 'PAYMENT_REQUEST':
        try {
          return PaymentRequestMessage(QRPayload.fromJson(data));
        } catch (e) {
          throw const FormatException('Payment request QR is missing fields.');
        }

      case 'TRANSACTION_RECEIPT':
        final txJson = data['transaction'];
        if (txJson is! Map<String, dynamic>) {
          throw const FormatException('Receipt QR is missing transaction data.');
        }
        try {
          return TransactionReceiptMessage(Transaction.fromJson(txJson));
        } catch (e) {
          throw const FormatException('Receipt QR contains an invalid transaction.');
        }

      default:
        throw FormatException('Unsupported QR code type: ${data['type']}.');
    }
  }
}

/// Message 1: a receiver asking to be paid.
class PaymentRequestMessage extends QrMessage {
  const PaymentRequestMessage(this.payload);

  final QRPayload payload;
}

/// Message 2: a payer handing a created transaction to the receiver.
class TransactionReceiptMessage extends QrMessage {
  const TransactionReceiptMessage(this.transaction);

  final Transaction transaction;
}

/// Serialize a transaction into the QR string the other device will scan.
String encodeTransactionReceipt(Transaction tx) {
  return jsonEncode({
    'version': '1.0',
    'type': 'TRANSACTION_RECEIPT',
    'transaction': tx.toJson(),
  });
}
